#!/bin/bash
# Rewrites data/synapse/homeserver.yaml for Majordome: Postgres, no federation, no registration,
# no presence, no URL previews. Keeps the secrets generated by `synapse generate`.
# Usage: run from the deploy directory on the server, after `synapse generate`.
set -euo pipefail
cd "$(dirname "$0")/.."
source .env

HS=data/synapse/homeserver.yaml
get() { grep -E "^$1:" "$HS" | head -1 | cut -d' ' -f2-; }
REG_SECRET=$(get registration_shared_secret)
MACAROON=$(get macaroon_secret_key)
FORM=$(get form_secret)

APPSERVICES=""
for f in data/synapse/appservices/*.yaml; do
  [ -e "$f" ] && APPSERVICES+="  - /data/appservices/$(basename "$f")"$'\n'
done

cat > "$HS" <<YAML
# Managed by deploy/scripts/configure-synapse.sh — edits will be overwritten.
server_name: "${SERVER_NAME}"
pid_file: /data/homeserver.pid
public_baseurl: "http://synapse:8008/"

listeners:
  - port: 8008
    type: http
    tls: false
    x_forwarded: false
    resources:
      - names: [client]   # no federation listener
        compress: false

database:
  name: psycopg2
  args:
    host: postgres
    user: synapse
    password: "${SYNAPSE_DB_PASSWORD}"
    dbname: synapse
    cp_min: 2
    cp_max: 10

# --- Private, single-user homeserver ---
federation_domain_whitelist: []      # no outbound federation
trusted_key_servers: []
allow_public_rooms_over_federation: false
enable_registration: false
url_preview_enabled: false           # no outbound fetches triggered by message content
presence:
  enabled: false
report_stats: false

log_config: "/data/${SERVER_NAME}.log.config"
media_store_path: /data/media_store
signing_key_path: "/data/${SERVER_NAME}.signing.key"

registration_shared_secret: ${REG_SECRET}
macaroon_secret_key: ${MACAROON}
form_secret: ${FORM}

app_service_config_files:
${APPSERVICES:-  []}
YAML
# An empty list must be inline, not an indented "[]" item.
sed -i -z 's/app_service_config_files:\n  \[\]/app_service_config_files: []/' "$HS"
echo "Wrote $HS ($(echo -n "$APPSERVICES" | grep -c . || true) appservice(s))"
